            else scale
            if (is.null(sd)) 
                stop("Provide 'scale_diag' (preferred) or 'scale'.")
            if (!"python.builtin.object" %in% class(loc)) 
                loc <- jnp$array(loc)
            if (!"python.builtin.object" %in% class(sd)) 
                sd <- jnp$array(sd)
            k <- as.integer(tail(.shape_of(loc), 1L))
            sample_fn <- function(sample_shape = NULL, seed = NULL) {
