                    if (in_channels <= out_channels) {
                      mat <- jax$random$orthogonal(subkey, n = out_channels)[0:in_channels, 
                        ]
                    }
                    else {
                      mat <- jnp$transpose(jax$random$orthogonal(subkey, 
                        n = in_channels))[, 1:out_channels]
                    }
                    kernels[[k]] <- mat
                  }
                  jnp$stack(kernels, axis = 0L)
                }
