                ")", collapse = "")
            rez <- qdapRegex::rm_between_multiple(rez, left = "frac{1}{ ", 
                right = " }", replace = " REPLACE_HERE ")
            rez <- gsub(rez, pattern = "REPLACE_HERE", replace = rez_replace_with)
