        zer <- unlist(strsplit(zer, split = "-"))
        if (length(zer) > 1) {
            zer <- sapply(zer, function(rez) {
                Transform2jnp(rez, jnp_transform = "jnp$multiply")
            })
            zer <- Collapse2jnp(zer, jnp_transform = "jnp$subtract")
        }
        zer <- unlist(strsplit(zer, split = "\\+"))
