}, analysis2_resolve_outer_iterations <- function(opts, default) {
    raw <- opts$outer %||% if (length(opts$positional) > 0L) 
        opts$positional[[1]]
    else NULL
    if (is.null(raw) || !nzchar(raw)) {
        return(as.integer(default))
    }
    parts <- strsplit(as.character(raw), ",", fixed = TRUE)[[1]]
    as.integer(trimws(parts))
}, analysis2_row_to_list <- function(row) {
    stopifnot(nrow(row) == 1L)
    out <- vector("list", length = ncol(row))
    names(out) <- names(row)
    for (name in names(row)) {
        value <- row[[name]][[1]]
        numeric_value <- suppressWarnings(analysis2_f2n(value))
        out[[name]] <- if (!is.na(numeric_value)) 
            numeric_value
        else as.character(value)
    }
    out
}, analysis2_scalar_df <- function(values) {
    as.data.frame(values, stringsAsFactors = FALSE, check.names = FALSE)
}, analysis2_order_grid <- function(grid, outer_iterations) {
    grid <- grid[order(grid$BaseID), , drop = FALSE]
    if (nrow(grid) == 0L || length(outer_iterations) == 0L) {
        return(grid)
    }
    first_outer <- outer_iterations[[1]]
    if (is.na(first_outer) || first_outer < 1L || first_outer > 
        nrow(grid)) {
        return(grid)
    }
    if (!isTRUE(grid$BaseID[[first_outer]]%%2 == 0)) {
        return(grid)
    }
    even_rows <- grid$BaseID%%2 == 0
    if (!any(even_rows)) {
        return(grid)
    }
    grid[even_rows, ] <- grid[even_rows, ][order(apply(grid[even_rows, 
        , drop = FALSE], 1, function(zr) rlang::hash(paste(zr, 
        collapse = "_")))), , drop = FALSE]
    grid
}, analysis2_validate_outer_iterations <- function(grid, outer_iterations, 
    grid_file) {
    if (length(outer_iterations) == 0L) {
        stop("No outer iterations were requested.", call. = FALSE)
    }
    bad <- outer_iterations[is.na(outer_iterations) | outer_iterations < 
        1L | outer_iterations > nrow(grid)]
    if (length(bad) == 0L) {
        return(invisible(outer_iterations))
    }
    stop("Requested outer iteration(s) outside the grid bounds for ", 
        grid_file, ": ", paste(bad, collapse = ", "), ". Valid rows are between 1 and ", 
        nrow(grid), ".", call. = FALSE)
}, analysis2_require_ndm <- function() {
    pkg <- tryCatch(utils::packageName(), error = function(e) NULL)
    if (!is.null(pkg) && nzchar(pkg)) {
        return(pkg)
